// ui_my_saves.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_my_saves

async function ui_my_saves (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="board-wrapper">
      <header class="board-header">
        <h1 class="board-title">My Saved Board</h1>
        <button class="btn-create">
          <span>Create</span>
          <span class="plus-icon"></span>
        </button>
      </header>

      <nav class="board-tabs">
        <span class="tab active">Pins</span>
        <span class="tab">Forked</span>
        <span class="tab">Dataset</span>
        <span class="tab">My Components</span>
      </nav>

      <div class="card-container">
        <div class="board-card">
          <div class="preview-grid">
            <div class="main-thumb">
              <span class="placeholder-icon"></span>
              <div class="edit-badge">
                <span class="brush-icon"></span>
              </div>
            </div>
            <div class="sub-thumbs">
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
            </div>
          </div>
          <div class="card-meta">
            <h3 class="card-title">App interfaces</h3>
            <p class="card-count">10 Pins</p>
          </div>
        </div>

        <div class="board-card">
          <div class="preview-grid">
            <div class="main-thumb">
              <span class="placeholder-icon"></span>
            </div>
            <div class="sub-thumbs">
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
            </div>
          </div>
          <div class="card-meta">
            <h3 class="card-title">My saves</h3>
            <p class="card-count">2 Pins</p>
          </div>
        </div>

        <div class="board-card">
          <div class="preview-grid">
            <div class="main-thumb">
              <span class="placeholder-icon"></span>
            </div>
            <div class="sub-thumbs">
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
              <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
            </div>
          </div>
          <div class="card-meta">
            <h3 class="card-title">UI components</h3>
            <p class="card-count">7 Pins</p>
          </div>
        </div>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const plus_icon = shadow.querySelector('.plus-icon')
  const brush_icon = shadow.querySelector('.brush-icon')
  const placeholders = shadow.querySelectorAll('.placeholder-icon')

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    const [plusSvg = '', imagePlaceholderSvg = '', brushSvg = ''] = data
    
    if (plus_icon && plusSvg) plus_icon.innerHTML = plusSvg
    if (brush_icon && brushSvg) brush_icon.innerHTML = brushSvg
    
    if (imagePlaceholderSvg) {
      placeholders.forEach(el => {
        el.innerHTML = imagePlaceholderSvg
      })
    }
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        }
      },

      drive: {
        'icons/': {
          'plus.svg': { '$ref': 'plus.svg' },
          'image_placeholder.svg': { '$ref': 'image_placeholder.svg' },
          'brush.svg': { '$ref': 'brush.svg' }
        },

        'style/ui_my_saves.css': {
          '$ref': 'ui_my_saves.css'
        }
      }
    }
  }
}